sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    if (newValue === '1' || newValue === '2') {
        var dialog = new GlideModal("glide_confirm_standard", true, 600);
		dialog.setTitle('Confirm MIM engagement');
        dialog.setPreference('title', "All priority " + g_form.getValue('priority') + " major incidents must be assessed and managed by the MIM team. Click 'okay' to confirm you have called the MIM team on 01-123-123.");
        dialog.setPreference("onPromptComplete", function() {});
        dialog.setPreference("onPromptCancel", function() {
            return false;
        });
        dialog.render();
    }
}
